/**
 * Editorial attribution validator. Ensures content has real editorial
 * ownership, not anonymous auto-generated text:
 *   - About page identifies the publisher
 *   - Contact page has a real email
 *   - Tool content does not pretend to be authored by an AI
 *   - No placeholder author names ("John Doe", "Jane Smith", etc.)
 *   - FAQ items are first-party (not lifted from competitors verbatim)
 */

import { walkFiles, readText, pathExists } from '../../utils/file-system';
import { PATHS } from '../../utils/constants';
import { error, warning, type Violation } from '../../utils/validation-result';

const PLACEHOLDER_AUTHORS = [
  'john doe',
  'jane doe',
  'jane smith',
  'john smith',
  'admin',
  'anonymous',
  'a. nonymous',
  'author name',
  'your name',
];

const AI_DISCLOSURE_MARKERS = [
  'generated by ai',
  'written by ai',
  'created by chatgpt',
  'ai-generated',
];

const CONTACT_EMAIL = 'hello@ahadex.online';

export async function run(): Promise<Violation[]> {
  const violations: Violation[] = [];

  // Rule 1: Contact page has real email.
  const contactPath = `${PATHS.srcPages}/Contact.tsx`;
  if (!(await pathExists(contactPath))) {
    violations.push(
      error('contact-page-missing', 'src/pages/Contact.tsx is missing.', {
        file: 'src/pages/Contact.tsx',
      }),
    );
  } else {
    const src = await readText(contactPath);
    if (!src.includes(CONTACT_EMAIL) && !/mailto:/.test(src)) {
      violations.push(
        error('contact-no-email', 'Contact page has no real contact method (mailto or email).', {
          file: 'src/pages/Contact.tsx',
          hint: `Include ${CONTACT_EMAIL} or a mailto link.`,
        }),
      );
    }
  }

  // Rule 2: About page identifies the publisher.
  const aboutPath = `${PATHS.srcPages}/About.tsx`;
  if (!(await pathExists(aboutPath))) {
    violations.push(
      error('about-page-missing', 'src/pages/About.tsx is missing.', {
        file: 'src/pages/About.tsx',
      }),
    );
  } else {
    const src = await readText(aboutPath);
    if (!/AHADEX|ahadex/i.test(src)) {
      violations.push(
        warning('about-no-publisher', 'About page does not identify the publisher.', {
          file: 'src/pages/About.tsx',
        }),
      );
    }
  }

  // Rule 3: content files must not contain placeholder authors.
  const contentFiles = await walkFiles(PATHS.src, { extensions: ['.ts', '.tsx'] });
  for (const file of contentFiles) {
    const relPath = file
      .substring(PATHS.root.length + 1)
      .split('\\')
      .join('/');
    if (relPath.endsWith('.test.ts') || relPath.endsWith('.test.tsx')) continue;

    const src = await readText(file);
    const lower = src.toLowerCase();

    for (const placeholder of PLACEHOLDER_AUTHORS) {
      // Only flag when used as an "author" attribution.
      const pattern = new RegExp(
        `author\\s*:\\s*['"\`]${placeholder.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}`,
        'i',
      );
      if (pattern.test(src)) {
        violations.push(
          error('placeholder-author', `Placeholder author "${placeholder}" found.`, {
            file: relPath,
            hint: 'Use a real editorial attribution.',
          }),
        );
      }
    }

    // Rule 4: no explicit AI authorship claims.
    for (const marker of AI_DISCLOSURE_MARKERS) {
      if (lower.includes(marker)) {
        violations.push(
          error('ai-authorship-claim', `Content claims AI authorship: "${marker}".`, {
            file: relPath,
            hint: 'Google and AdSense penalize AI-authored bulk content.',
          }),
        );
      }
    }
  }

  return violations;
}
